package br.com.onda;
import android.app.*;
import android.content.*;
import android.graphics.Bitmap;
import android.net.Uri;
import android.provider.DocumentsContract;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

public class AutoDestinationTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();
 private final String URL="https://raw.githubusercontent.com/cristianoarakaki-cpu/Arakaki/245b693e64cf5b5b33bc2a5f491a607f6a435655/Onda/tests/fixtures/download.mp4";
 private final Map<String,Map<String,?>> saved=new HashMap<>();private final List<Uri> created=new ArrayList<>();private Activity activity;private Uri tree;
 private final List<String> pickers=Collections.synchronizedList(new ArrayList<>());
 private final Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){String action=intent.getAction();if(Intent.ACTION_CREATE_DOCUMENT.equals(action)||Intent.ACTION_OPEN_DOCUMENT_TREE.equals(action)){pickers.add(action);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};
 @Before public void setup(){for(String name:Arrays.asList(OndaFolders.PREF,"downloads",DownloadHistory.PREF)){saved.put(name,c.getSharedPreferences(name,0).getAll());c.getSharedPreferences(name,0).edit().clear().commit();}for(UriPermission grant:c.getContentResolver().getPersistedUriPermissions())if(grant.isReadPermission()&&grant.isWritePermission()&&DocumentsContract.isTreeUri(grant.getUri())){tree=grant.getUri();break;}assertNotNull("Folder grant from Conecta UI is required",tree);ins.addMonitor(monitor);}
 @After public void cleanup()throws Exception{c.stopService(new Intent(c,MediaDownloadService.class));for(int i=0;i<50&&MediaDownloadService.activeDownload;i++)Thread.sleep(100);if(activity!=null)ins.runOnMainSync(activity::finish);ins.removeMonitor(monitor);for(Uri uri:created)try{DocumentsContract.deleteDocument(c.getContentResolver(),uri);}catch(Exception ignored){}for(Map.Entry<String,Map<String,?>> entry:saved.entrySet()){SharedPreferences.Editor editor=c.getSharedPreferences(entry.getKey(),0).edit().clear();for(Map.Entry<String,?> item:entry.getValue().entrySet()){Object value=item.getValue();String key=item.getKey();if(value instanceof String)editor.putString(key,(String)value);else if(value instanceof Boolean)editor.putBoolean(key,(Boolean)value);else if(value instanceof Long)editor.putLong(key,(Long)value);else if(value instanceof Integer)editor.putInt(key,(Integer)value);else if(value instanceof Float)editor.putFloat(key,(Float)value);}editor.commit();}}
 private void set(Object object,String name,Object value)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);f.set(object,value);}
 private Object get(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 private void start(){activity=ins.startActivitySync(new Intent(c,DownloadsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();}
 private void pick(String title)throws Exception{ins.runOnMainSync(()->{try{set(activity,"title",title);set(activity,"source",URL);Method method=DownloadsActivity.class.getDeclaredMethod("pick",YoutubeDownloads.Option.class);method.setAccessible(true);method.invoke(activity,new YoutubeDownloads.Option("MP4 original",URL,null,"mp4","video/mp4",true,""));}catch(Exception e){throw new RuntimeException(e);}});}
 private Uri savedFile(String title)throws Exception{long deadline=System.currentTimeMillis()+90000;while(System.currentTimeMillis()<deadline){SharedPreferences prefs=c.getSharedPreferences("downloads",0);String status=prefs.getString("status","");if(status.startsWith("Operação interrompida"))fail(status);if(title.equals(prefs.getString("last_title",""))&&!MediaDownloadService.activeDownload){Uri uri=Uri.parse(prefs.getString("last_uri",""));created.add(uri);assertTrue(DocumentsContract.getDocumentId(uri).contains("/Onda/Vídeos/"));return uri;}Thread.sleep(100);}throw new AssertionError("Automatic download did not finish");}
 @Test public void firstRootChoiceIsRememberedAndSecondDownloadNeedsNoPicker()throws Exception{start();String title="Auto-native-"+UUID.randomUUID();pick(title);boolean[] cancelled={false};for(int i=0;i<100;i++){ins.runOnMainSync(()->{try{cancelled[0]=!pickers.isEmpty()&&!(Boolean)get(activity,"picking");}catch(Exception e){throw new RuntimeException(e);}});if(cancelled[0])break;Thread.sleep(100);}assertTrue("Initial folder authorization was not requested",cancelled[0]);assertEquals(Collections.singletonList(Intent.ACTION_OPEN_DOCUMENT_TREE),pickers);
  ins.runOnMainSync(()->{try{set(activity,"pending",new YoutubeDownloads.Option("MP4 original",URL,null,"mp4","video/mp4",true,""));set(activity,"picking",true);((DownloadsActivity)activity).onActivityResult(923,Activity.RESULT_OK,new Intent().setData(tree).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(Exception e){throw new RuntimeException(e);}});
  savedFile(title);assertEquals(tree.toString(),c.getSharedPreferences(OndaFolders.PREF,0).getString("tree",""));assertTrue(OndaFolders.enabled(c));String second="Auto-native-"+UUID.randomUUID();pick(second);savedFile(second);assertEquals("Second download opened a picker",1,pickers.size());
  Bitmap image=ins.getUiAutomation().takeScreenshot();if(image!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"auto-destination.png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}
 }
 @Test public void restoresOnlyTheAuthorizedRootUsedByLastCompletedDownload()throws Exception{OndaFolders.configure(c,tree);Uri file=OndaFolders.create(c,"m4a","Auto-native-restore-"+UUID.randomUUID());created.add(file);try(InputStream input=ins.getContext().getAssets().open("audio.m4a");OutputStream output=c.getContentResolver().openOutputStream(file)){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1)output.write(b,0,n);}c.getSharedPreferences("downloads",0).edit().putString("last_uri",file.toString()).commit();c.getSharedPreferences(OndaFolders.PREF,0).edit().clear().commit();assertTrue(OndaFolders.restoreDownloadRoot(c));assertEquals(tree.toString(),c.getSharedPreferences(OndaFolders.PREF,0).getString("tree",""));assertTrue(OndaFolders.enabled(c));}
 @Test public void oneOffOtherLocationDoesNotDisableAutomaticDestination()throws Exception{OndaFolders.configure(c,tree);start();ins.runOnMainSync(()->{try{set(activity,"otherLocationOnce",true);}catch(Exception e){throw new RuntimeException(e);}});pick("Auto-native-manual");for(int i=0;i<50&&pickers.isEmpty();i++)Thread.sleep(100);assertEquals(Collections.singletonList(Intent.ACTION_CREATE_DOCUMENT),pickers);assertTrue(OndaFolders.automatic(c));ins.runOnMainSync(()->{try{assertFalse((Boolean)get(activity,"otherLocationOnce"));}catch(Exception e){throw new RuntimeException(e);}});}
 @Test public void playlistRootRemainsDefaultEvenIfTheOperationFails()throws Exception{start();ins.runOnMainSync(()->{try{set(activity,"pendingQueue","[]");set(activity,"pendingFormat","mp3");set(activity,"rememberNextTree",true);set(activity,"picking",true);((DownloadsActivity)activity).onActivityResult(922,Activity.RESULT_OK,new Intent().setData(tree));}catch(Exception e){throw new RuntimeException(e);}});long deadline=System.currentTimeMillis()+10000;while(System.currentTimeMillis()<deadline){if(OndaFolders.enabled(c)&&!MediaDownloadService.activeDownload&&c.getSharedPreferences("downloads",0).getString("status","").startsWith("Operação interrompida"))break;Thread.sleep(100);}assertTrue(OndaFolders.enabled(c));assertEquals(tree.toString(),c.getSharedPreferences(OndaFolders.PREF,0).getString("tree",""));assertTrue(pickers.isEmpty());}
 @Test public void rootGrantIsRememberedAfterPendingFormatWasLost()throws Exception{start();ins.runOnMainSync(()->((DownloadsActivity)activity).onActivityResult(923,Activity.RESULT_OK,new Intent().setData(tree)));long deadline=System.currentTimeMillis()+10000;while(System.currentTimeMillis()<deadline){boolean[] done={false};ins.runOnMainSync(()->{try{done[0]=OndaFolders.enabled(c)&&!(Boolean)get(activity,"picking");}catch(Exception e){throw new RuntimeException(e);}});if(done[0])break;Thread.sleep(100);}assertTrue(OndaFolders.enabled(c));assertEquals(tree.toString(),c.getSharedPreferences(OndaFolders.PREF,0).getString("tree",""));assertFalse(MediaDownloadService.activeDownload);assertTrue(pickers.isEmpty());}

}
